import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { BrowserClientHostAuthorityReplacementWait } from './browser-client-host-authority-replacement-wait'

describe('BrowserClientHostAuthorityReplacementWait', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('expires exactly once, at the grace deadline', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const expire = vi.fn()

    wait.arm(expire)

    expect(wait.armed).toBe(true)
    vi.advanceTimersByTime(999)
    expect(expire).not.toHaveBeenCalled()
    vi.advanceTimersByTime(1)
    expect(expire).toHaveBeenCalledOnce()
    expect(wait.armed).toBe(false)
    vi.advanceTimersByTime(10_000)
    expect(expire).toHaveBeenCalledOnce()
  })

  // Bursts of mismatch errors must not postpone retirement indefinitely.
  it('keeps the first deadline when armed again while already armed', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const first = vi.fn()
    const second = vi.fn()

    wait.arm(first)
    vi.advanceTimersByTime(900)
    wait.arm(second)
    vi.advanceTimersByTime(100)

    expect(first).toHaveBeenCalledOnce()
    expect(second).not.toHaveBeenCalled()
  })

  it('never expires after a cancel', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const expire = vi.fn()
    wait.arm(expire)

    wait.cancel()

    expect(wait.armed).toBe(false)
    vi.advanceTimersByTime(10_000)
    expect(expire).not.toHaveBeenCalled()
  })

  it('is re-armable after a cancel and after an expiry', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const cancelled = vi.fn()
    const rearmed = vi.fn()
    wait.arm(cancelled)
    wait.cancel()

    wait.arm(rearmed)
    vi.advanceTimersByTime(1_000)

    expect(cancelled).not.toHaveBeenCalled()
    expect(rearmed).toHaveBeenCalledOnce()

    const afterExpiry = vi.fn()
    wait.arm(afterExpiry)
    vi.advanceTimersByTime(1_000)
    expect(afterExpiry).toHaveBeenCalledOnce()
  })
})

import type {
  BrowserClientHostCommandEvent,
  BrowserClientHostLeaseAuthority
} from '../../shared/browser-client-host-protocol'
import { describe, expect, it, vi } from 'vitest'
import { BrowserHostCommandLedger } from '../runtime/browser-host/browser-host-command-ledger'
import { BrowserClientHostCommandDispatcher } from './browser-client-host-command-dispatcher'

const authority: BrowserClientHostLeaseAuthority & {
  pageCommandProtocolVersion: 1
  pageReconciliationProtocolVersion: 1
} = {
  authorityRuntimeId: 'runtime-a',
  authorityEpoch: 'epoch-new',
  browserHostClientId: 'host-a',
  browserHostGeneration: 3,
  pageCommandProtocolVersion: 1,
  pageReconciliationProtocolVersion: 1
}

const previousAuthority = {
  authorityRuntimeId: 'runtime-a',
  authorityEpoch: 'epoch-old',
  browserHostClientId: 'host-a',
  browserHostGeneration: 2,
  pageHostGeneration: 7
}

function event(
  command: BrowserClientHostCommandEvent['command'],
  overrides: Partial<BrowserClientHostCommandEvent> = {}
): BrowserClientHostCommandEvent {
  return {
    type: 'command',
    ...authority,
    browserPageId: 'page-a',
    pageHostGeneration: command.type === 'closePage' ? 7 : 8,
    commandSequence: 1,
    commandId: `${command.type}-a`,
    command,
    ...overrides
  }
}

describe('browser reconciliation command ordering', () => {
  it.each([
    {
      type: 'reclaimPage' as const,
      previousAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    },
    {
      type: 'restorePage' as const,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    },
    { type: 'closePage' as const, targetAuthority: previousAuthority }
  ])('admits $type as an authenticated first client-dispatch command', async (command) => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })

    await expect(dispatcher.dispatch(event(command))).resolves.toEqual({ status: 'completed' })
    expect(handler).toHaveBeenCalledOnce()
  })

  it('deduplicates exact reclaim bootstrap and rejects changed prior authority', async () => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
    const reclaim = event({
      type: 'reclaimPage',
      previousAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    })

    const first = dispatcher.dispatch(reclaim)
    const duplicate = dispatcher.dispatch(reclaim)
    await expect(first).resolves.toEqual({ status: 'completed' })
    await expect(duplicate).resolves.toEqual({ status: 'completed' })
    expect(handler).toHaveBeenCalledOnce()
    expect(() =>
      dispatcher.dispatch({
        ...reclaim,
        command: {
          ...reclaim.command,
          previousAuthority: { ...previousAuthority, authorityEpoch: 'different' }
        }
      } as BrowserClientHostCommandEvent)
    ).toThrow('browser_host_command_sequence_conflict')
  })

  it('snapshots nested reconciliation authority on both sides of dispatch', async () => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
    const clientAuthority = { ...previousAuthority }
    const clientEvent = event({
      type: 'reclaimPage',
      previousAuthority: clientAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    })

    const dispatched = dispatcher.dispatch(clientEvent)
    clientAuthority.authorityEpoch = 'mutated-client'
    await dispatched
    const accepted = handler.mock.calls[0]?.[0] as BrowserClientHostCommandEvent
    expect(accepted.command).toMatchObject({
      previousAuthority: expect.objectContaining({ authorityEpoch: 'epoch-old' })
    })
    expect(
      Object.isFrozen(accepted.command.type === 'reclaimPage' && accepted.command.previousAuthority)
    ).toBe(true)

    const delivery = vi.fn()
    const ledger = new BrowserHostCommandLedger({ authority })
    ledger.attach(delivery)
    const serverAuthority = { ...previousAuthority }
    ledger.issue({
      browserPageId: 'page-b',
      pageHostGeneration: 8,
      command: {
        type: 'reclaimPage',
        previousAuthority: serverAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      }
    })
    serverAuthority.authorityEpoch = 'mutated-server'
    const emitted = delivery.mock.calls[0]?.[0] as BrowserClientHostCommandEvent
    expect(emitted.command).toMatchObject({
      previousAuthority: expect.objectContaining({ authorityEpoch: 'epoch-old' })
    })
    expect(
      Object.isFrozen(emitted.command.type === 'reclaimPage' && emitted.command.previousAuthority)
    ).toBe(true)
  })

  it.each(['reclaimPage', 'restorePage'] as const)(
    'cancels navigation when %s bootstrap fails',
    async (type) => {
      const handler = vi
        .fn()
        .mockResolvedValueOnce({ status: 'failed', errorCode: 'bootstrap_failed' })
      const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
      const bootstrap =
        type === 'reclaimPage'
          ? {
              type,
              previousAuthority,
              browserProfileId: 'profile-a',
              executionHostKey: 'host-key-a'
            }
          : {
              type,
              browserProfileId: 'profile-a',
              executionHostKey: 'host-key-a'
            }
      const first = dispatcher.dispatch(event(bootstrap))
      const navigate = dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: `${type}-navigate` }
        )
      )

      await expect(first).resolves.toEqual({
        status: 'failed',
        errorCode: 'bootstrap_failed'
      })
      await expect(navigate).resolves.toEqual({
        status: 'failed',
        errorCode: 'browser_host_command_dependency_failed'
      })
      expect(handler).toHaveBeenCalledOnce()
    }
  )

  it('makes an exact close terminal while allowing navigate after reclaim', async () => {
    const dispatcher = new BrowserClientHostCommandDispatcher({
      authority,
      handler: vi.fn().mockResolvedValue({ status: 'completed' })
    })
    await dispatcher.dispatch(
      event({
        type: 'reclaimPage',
        previousAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      })
    )
    await expect(
      dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-a' }
        )
      )
    ).resolves.toEqual({ status: 'completed' })

    const closing = new BrowserClientHostCommandDispatcher({
      authority,
      handler: vi.fn().mockResolvedValue({ status: 'completed' })
    })
    await closing.dispatch(event({ type: 'closePage', targetAuthority: previousAuthority }))
    expect(() =>
      closing.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-after-close', pageHostGeneration: 7 }
        )
      )
    ).toThrow('browser_host_page_generation_stale')
  })

  it('allows the same generation to continue after a failed close', async () => {
    const handler = vi
      .fn()
      .mockResolvedValueOnce({ status: 'failed', errorCode: 'authority_stale' })
      .mockResolvedValueOnce({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })

    await expect(
      dispatcher.dispatch(event({ type: 'closePage', targetAuthority: previousAuthority }))
    ).resolves.toEqual({ status: 'failed', errorCode: 'authority_stale' })
    await expect(
      dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-after-failed-close', pageHostGeneration: 7 }
        )
      )
    ).resolves.toEqual({ status: 'completed' })
  })

  it('issues reconciliation bootstrap commands from the server ledger without create', () => {
    const delivery = vi.fn()
    const ledger = new BrowserHostCommandLedger({ authority })
    ledger.attach(delivery)

    const reclaim = ledger.issue({
      browserPageId: 'page-a',
      pageHostGeneration: 8,
      command: {
        type: 'reclaimPage',
        previousAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      }
    })
    const navigate = ledger.issue({
      browserPageId: 'page-a',
      pageHostGeneration: 8,
      command: { type: 'navigate', url: 'https://remote.internal/' }
    })
    const close = ledger.issue({
      browserPageId: 'page-b',
      pageHostGeneration: 9,
      resultAdmission: 'reconciliation',
      command: {
        type: 'closePage',
        targetAuthority: { ...previousAuthority, pageHostGeneration: 9 }
      }
    })

    expect(reclaim.event.commandSequence).toBe(1)
    expect(navigate.event.commandSequence).toBe(2)
    expect(close.event.commandSequence).toBe(1)
    expect(delivery).toHaveBeenCalledTimes(3)
    expect(() =>
      ledger.issue({
        browserPageId: 'page-b',
        pageHostGeneration: 9,
        command: { type: 'navigate', url: 'https://after-close.invalid/' }
      })
    ).toThrow('browser_host_command_page_terminal')
  })
})

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { createCommand, createHarness } from './browser-client-page-command-executor-test-harness'

describe('BrowserClientPageCommandExecutor authority fencing', () => {
  beforeEach(() => vi.restoreAllMocks())

  it('does not retain a page when close races its in-flight creation', async () => {
    const { dependencies, executor, order, route } = createHarness()
    let resolveRoute = (_route: typeof route): void => {}
    dependencies.retainNetworkRoute.mockImplementationOnce(
      () =>
        new Promise((resolve) => {
          resolveRoute = resolve
        })
    )
    const creating = executor.handle(createCommand('createPage'), new AbortController().signal)
    await Promise.resolve()

    await expect(executor.close()).rejects.toThrow('Browser client page executor cleanup failed')
    resolveRoute(route)

    await expect(creating).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    expect(executor.hasPage('page-a', 7)).toBe(false)
    expect(order).toEqual(['release-route'])
  })

  it('retires every retained page before fencing later commands', async () => {
    const { executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    await executor.close()

    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
  })

  it('revokes retained navigation once without inferring guest destruction', async () => {
    const { dependencies, executor, order, route } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    executor.fenceNavigation()
    executor.fenceNavigation()

    expect(dependencies.routeWebContents.revokeNavigation).toHaveBeenCalledOnce()
    expect(order.at(-1)).toBe('revoke-navigation')
    expect(route.release).not.toHaveBeenCalled()
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    await executor.close()
  })

  it('retains inventory while fencing old pages and uses the replacement route identity', async () => {
    const { dependencies, executor } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    executor.beginAuthorityTransition()

    expect(executor.snapshotPageInventory()).toEqual([
      expect.objectContaining({ browserPageId: 'page-a', authorityRuntimeId: 'runtime-a' })
    ])
    expect(dependencies.routeWebContents.revokeNavigation).toHaveBeenCalledOnce()
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })

    executor.completeAuthorityTransition({
      authorityConnectionIdentity: 'authority-record-b',
      pairingAuthorityConnectionIdentity: 'pairing-authority-record-b',
      legacyAuthorityConnectionIdentity: 'legacy-authority-record-b'
    })
    await expect(
      executor.handle(
        createCommand('navigate', {
          authorityRuntimeId: 'runtime-b',
          authorityEpoch: 'epoch-b',
          browserHostGeneration: 1
        }),
        new AbortController().signal
      )
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_generation_stale'
    })
    expect(dependencies.routeWebContents.navigateGuest).not.toHaveBeenCalled()

    await executor.retirePage('page-a', 7)
    await executor.handle(
      createCommand('createPage', {
        authorityRuntimeId: 'runtime-b',
        authorityEpoch: 'epoch-b',
        browserPageId: 'page-b',
        pageHostGeneration: 1
      }),
      new AbortController().signal
    )

    expect(dependencies.routeSessions.preparePage).toHaveBeenLastCalledWith(
      expect.objectContaining({
        identity: expect.objectContaining({ authorityConnectionIdentity: 'authority-record-b' })
      })
    )
  })

  it('releases an in-flight old-authority create during transition', async () => {
    const { dependencies, executor, order, route } = createHarness()
    let resolveRoute = (_route: typeof route): void => {}
    dependencies.retainNetworkRoute.mockImplementationOnce(
      () =>
        new Promise((resolve) => {
          resolveRoute = resolve
        })
    )
    const creating = executor.handle(createCommand('createPage'), new AbortController().signal)
    await Promise.resolve()

    executor.beginAuthorityTransition()
    resolveRoute(route)

    await expect(creating).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    expect(executor.snapshotPageInventory()).toEqual([])
    expect(dependencies.routeWebContents.grantNavigation).not.toHaveBeenCalled()
    expect(order).toEqual(['release-route'])
    executor.completeAuthorityTransition({
      authorityConnectionIdentity: 'authority-record-b',
      pairingAuthorityConnectionIdentity: 'pairing-authority-record-b',
      legacyAuthorityConnectionIdentity: 'legacy-authority-record-b'
    })
    await executor.close()
  })

  it('keeps transition fail-closed when navigation revocation throws', async () => {
    const { dependencies, executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)
    dependencies.routeWebContents.revokeNavigation.mockImplementationOnce(() => {
      order.push('revoke-navigation')
      throw new Error('transition revocation failed')
    })

    expect(() => executor.beginAuthorityTransition()).toThrow(
      'Browser client page navigation fencing failed'
    )
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })

    await executor.close()
    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
  })

  it('continues exact page cleanup when navigation revocation throws', async () => {
    const { dependencies, executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)
    dependencies.routeWebContents.revokeNavigation.mockImplementationOnce(() => {
      order.push('revoke-navigation')
      throw new Error('navigation revocation failed')
    })

    await expect(executor.close()).rejects.toMatchObject({
      message: 'Browser client page navigation fencing failed',
      errors: [expect.objectContaining({ message: 'navigation revocation failed' })]
    })

    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
  })
})

import { mkdtempSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { describe, expect, it, vi } from 'vitest'
import {
  browserHostClientIdentityPath,
  readOrCreateBrowserHostClientId
} from './browser-host-client-identity'

function profileDirectory(): string {
  return mkdtempSync(join(tmpdir(), 'orca-host-identity-'))
}

describe('browser host client identity', () => {
  it('keeps one hosting identity across relaunches of the same profile', () => {
    const directory = profileDirectory()

    const first = readOrCreateBrowserHostClientId(directory)
    const second = readOrCreateBrowserHostClientId(directory)

    expect(second).toBe(first)
    expect(first).toMatch(/^[0-9a-f-]{36}$/)
  })

  it('gives each Orca profile its own hosting identity', () => {
    expect(readOrCreateBrowserHostClientId(profileDirectory())).not.toBe(
      readOrCreateBrowserHostClientId(profileDirectory())
    )
  })

  it.each([
    ['unparseable content', 'not json at all'],
    ['a future store version', JSON.stringify({ version: 2, browserHostClientId: 'kept' })],
    ['a missing identity', JSON.stringify({ version: 1 })],
    ['a non-string identity', JSON.stringify({ version: 1, browserHostClientId: 7 })],
    ['an empty identity', JSON.stringify({ version: 1, browserHostClientId: '' })],
    [
      'an identity past the wire limit',
      JSON.stringify({ version: 1, browserHostClientId: 'x'.repeat(257) })
    ]
  ])('mints a fresh identity rather than trusting %s', (_label, contents) => {
    const directory = profileDirectory()
    writeFileSync(browserHostClientIdentityPath(directory), contents)

    const identity = readOrCreateBrowserHostClientId(directory)

    expect(identity).toMatch(/^[0-9a-f-]{36}$/)
    expect(readOrCreateBrowserHostClientId(directory)).toBe(identity)
  })

  it('still names the host when the profile cannot be written', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    const file = join(profileDirectory(), 'occupied')
    writeFileSync(file, 'not a directory')

    expect(readOrCreateBrowserHostClientId(join(file, 'nested'))).toMatch(/^[0-9a-f-]{36}$/)
    expect(warn).toHaveBeenCalled()
  })
})

