    const sendCalls = client.calls.filter((c) => c.method === 'terminal.send')
    expect(sendCalls).toHaveLength(2)
    expect(sendCalls[1]?.params.text).toBe('\x1b[200~/tmp/a.png\x1b[201~')
    expect(hook!.attachments).toEqual([])
